var i=`cap-theorem`;var o=41;var a={en:[{id:`T041-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`CAP Theorem`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Timeouts bound waiting, retries recover transient failures, and backoff spaces repeated attempts to avoid overload.`},{id:`B`,text:`ACID describes atomicity, consistency, isolation and durability of database transactions.`},{id:`C`,text:`PACELC extends CAP: if partitioned, choose between availability and consistency; else, even in normal operation, choose between latency and consistency.`},{id:`D`,text:`CAP states that, when a network partition occurs, a distributed data system cannot guarantee both linearizable consistency and availability for every request.`}]},{id:`T041-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`CAP Theorem`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Choose orchestration or choreography; record progress durably and make each step retry-safe.`},{id:`B`,text:`Define failure thresholds, observation windows, reset timeouts and probe traffic.`},{id:`C`,text:`Under partition, a consistency-oriented system may reject or delay operations to avoid contradictory answers; an availability-oriented system may accept operations that reconcile later.`},{id:`D`,text:`A strongly consistent cross-region read may require waiting for remote coordination, while a local replica responds faster with possible staleness.`}]},{id:`T041-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`},{id:`B`,text:`A moderation status must still prevent disallowed content from being published.`},{id:`C`,text:`A social feed might keep serving slightly stale content.`},{id:`D`,text:`Reusing its idempotency key must return the original outcome, not issue a second charge, even if the first response was lost.`}]},{id:`T041-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`CAP Theorem`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Do not classify every database permanently as CA, CP or AP; behavior is operation-specific and depends on fault assumptions.`},{id:`B`,text:`Long-running sagas expose temporary inconsistency.`},{id:`C`,text:`PACELC is a heuristic, not a complete specification of real systems.`},{id:`D`,text:`Consensus cannot defeat network partitions or guarantee progress without a quorum.`}]},{id:`T041-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Partition tolerance is a condition to handle, not a freely optional product feature.`}]}]},{id:`T041-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`CAP says a distributed system must permanently choose exactly two of three properties.`}]}]},{id:`T041-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`CAP alone does not capture latency or consistency choices during normal operation.`}]}]},{id:`T041-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`CAP Theorem`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Under partition, a consistency-oriented system may reject or delay operations to avoid contradictory answers; an availability-oriented system may accept operations that reconcile later.`},{id:`B`,text:`ACID means transactions can never fail or roll back.`},{id:`C`,text:`Under a partition, every node can remain fully consistent and fully available for writes.`},{id:`D`,text:`CAP states that, when a network partition occurs, a distributed data system cannot guarantee both linearizable consistency and availability for every request.`}]},{id:`T041-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`CAP Theorem`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`CAP alone does not capture latency or consistency choices during normal operation.`},{id:`B`,text:`CAP says a distributed system must permanently choose exactly two of three properties.`},{id:`C`,text:`When no partition exists, PACELC makes no consistency-latency trade-off.`},{id:`D`,text:`A social feed might keep serving slightly stale content.`}]},{id:`T041-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to explain a five-node Raft cluster losing two or three nodes, showing which writes remain possible and how safety differs from availability.`},{id:`B`,text:`Have an agent compare local stale reads and quorum reads for a two-region booking search. Require latency budgets, stale-data tolerance and an operational fallback.`},{id:`C`,text:`Have an agent design an order-payment-fulfillment saga with a state machine, idempotent steps, compensation table and an operator recovery procedure.`},{id:`D`,text:`Ask an agent to design reservation confirmation under a simulated partition, specifying exact success, timeout and retry semantics rather than a generic CP/AP label.`}]},{id:`T041-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What consistency guarantee do users actually need for reading and reserving inventory?`}]}]},{id:`T041-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`CAP Theorem`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T041-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage.`,b:!0},{t:` — propose three checks for `},{t:`CAP Theorem`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T041-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T041-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`CAP Theorem`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A reservation inventory should avoid confirming the same last room twice, so some write requests may wait during an outage.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T041-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Теорема CAP`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Timeout обмежує очікування, retry долає тимчасові збої, backoff розносить спроби в часі, щоб не перевантажувати систему.`},{id:`B`,text:`ACID описує атомарність, узгодженість, ізоляцію та довговічність транзакцій БД.`},{id:`C`,text:`PACELC розширює CAP: за partition постає вибір між доступністю й узгодженістю; в нормальному режимі — між затримкою й узгодженістю.`},{id:`D`,text:`CAP стверджує, що за мережевого розділення розподілене сховище не може одночасно гарантувати лінеаризовану узгодженість та доступність кожного запиту.`}]},{id:`T041-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Теорема CAP`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Оберіть оркестрацію або хореографію; надійно зберігайте прогрес і забезпечте безпечні повтори кроків.`},{id:`B`,text:`Визначте пороги помилок, вікно спостереження, час повторної перевірки та пробні запити.`},{id:`C`,text:`Під час partition система, орієнтована на узгодженість, відхиляє або затримує операції; орієнтована на доступність може приймати зміни з подальшим узгодженням.`},{id:`D`,text:`Сильно узгоджене читання між регіонами може чекати віддаленої координації, тоді як локальна репліка відповідає швидше, але іноді застаріло.`}]},{id:`T041-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`},{id:`B`,text:`Статус модерації все одно має блокувати недопустимий контент.`},{id:`C`,text:`Соціальна стрічка може продовжувати віддавати трохи застарілі дані.`},{id:`D`,text:`Повтор ключа має повертати початковий результат, а не виконувати друге списання, навіть якщо перша відповідь загубилась.`}]},{id:`T041-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Теорема CAP`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Не навішуйте назавжди ярлик CA, CP чи AP на будь-яку БД: поведінка залежить від операцій і моделі відмов.`},{id:`B`,text:`Тривала saga має проміжну неузгодженість.`},{id:`C`,text:`PACELC — евристика, а не повна специфікація системи.`},{id:`D`,text:`Консенсус не усуває partition і не гарантує прогресу без quorum.`}]},{id:`T041-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Стійкість до partition — умова роботи, а не довільна опція.`}]}]},{id:`T041-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`CAP стверджує, що розподілена система назавжди обирає рівно дві з трьох властивостей.`}]}]},{id:`T041-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`CAP не описує компроміси затримок у нормальній роботі.`}]}]},{id:`T041-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Теорема CAP`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Під час partition система, орієнтована на узгодженість, відхиляє або затримує операції; орієнтована на доступність може приймати зміни з подальшим узгодженням.`},{id:`B`,text:`ACID означає, що транзакції ніколи не завершуються помилкою і не відкочуються.`},{id:`C`,text:`Під час мережевого розділення всі вузли можуть водночас мати повну узгодженість і доступність запису.`},{id:`D`,text:`CAP стверджує, що за мережевого розділення розподілене сховище не може одночасно гарантувати лінеаризовану узгодженість та доступність кожного запиту.`}]},{id:`T041-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Теорема CAP`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`CAP не описує компроміси затримок у нормальній роботі.`},{id:`B`,text:`CAP стверджує, що розподілена система назавжди обирає рівно дві з трьох властивостей.`},{id:`C`,text:`Коли розділення немає, PACELC не описує компроміс узгодженості й затримки.`},{id:`D`,text:`Соціальна стрічка може продовжувати віддавати трохи застарілі дані.`}]},{id:`T041-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента пояснити Raft-кластер із п’яти вузлів після втрати двох або трьох, вказавши можливість запису й різницю між safety та availability.`},{id:`B`,text:`Попросіть агента порівняти локальні застарілі читання з quorum для пошуку бронювань у двох регіонах. Вимагайте бюджети затримки, допустиму неактуальність і fallback.`},{id:`C`,text:`Попросіть агента створити saga замовлення, оплати й доставки зі станами, ідемпотентними кроками, таблицею компенсацій та процедурою ручного відновлення.`},{id:`D`,text:`Попросіть агента спроєктувати підтвердження бронювання під час мережевого розділення, явно визначити успіх, timeout і повтори замість загальної позначки CP/AP.`}]},{id:`T041-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Яка гарантія узгодженості справді потрібна для читання та бронювання залишку?`}]}]},{id:`T041-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Теорема CAP`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T041-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Теорема CAP`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T041-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T041-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Теорема CAP`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Інвентар бронювань не має підтверджувати останній номер двічі, тому деякі записи можуть чекати під час збою.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:41,questions:a};export{s as default,a as questions,i as slug,o as topicId};